import{_ as t,c as a,o,ae as n}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse('{"title":"Introduction","description":"Introduction to MinecraftSounds Minecraft Music Pack Generator","frontmatter":{"title":"Introduction","description":"Introduction to MinecraftSounds Minecraft Music Pack Generator"},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md"}'),r={name:"en/guide/index.md"};function i(s,e,c,u,d,l){return o(),a("div",null,e[0]||(e[0]=[n('<h1 id="minecraftsounds-music-pack-generator-introduction" tabindex="-1">MinecraftSounds Music Pack Generator Introduction <a class="header-anchor" href="#minecraftsounds-music-pack-generator-introduction" aria-label="Permalink to &quot;MinecraftSounds Music Pack Generator Introduction&quot;">​</a></h1><p>This generator was created after discovering that many beginners want to play their own music or sound effects in Minecraft.</p><p>The software is built with Python and uses pyqt5 for the interface, with AI-assisted development.<br> The UI design features a Minecraft-style interface, making it very convenient to operate.</p><h2 id="what-is-a-music-pack" tabindex="-1">What is a Music Pack? <a class="header-anchor" href="#what-is-a-music-pack" aria-label="Permalink to &quot;What is a Music Pack?&quot;">​</a></h2><p>In Minecraft, a music pack (part of a Resource Pack) allows players to customize various sound effects in the game, including:</p><ul><li>Background music</li><li>Environmental sounds</li><li>Creature sounds</li><li>Block sounds</li><li>Interface sounds</li><li>And more</li></ul><p>By replacing or adding these sound effects, players can enjoy a completely new gaming experience.</p><h2 id="why-choose-minecraftsounds-music-pack-generator" tabindex="-1">Why Choose MinecraftSounds Music Pack Generator? <a class="header-anchor" href="#why-choose-minecraftsounds-music-pack-generator" aria-label="Permalink to &quot;Why Choose MinecraftSounds Music Pack Generator?&quot;">​</a></h2><h3 id="easy-to-use" tabindex="-1">Easy to Use <a class="header-anchor" href="#easy-to-use" aria-label="Permalink to &quot;Easy to Use&quot;">​</a></h3><p>Our design philosophy is &quot;enabling everyone to create their own music pack.&quot; Even if you have no prior knowledge, you can easily create a music pack through our intuitive interface.</p><h3 id="comprehensive-features" tabindex="-1">Comprehensive Features <a class="header-anchor" href="#comprehensive-features" aria-label="Permalink to &quot;Comprehensive Features&quot;">​</a></h3><ul><li><strong>Visual Editing</strong>: Drag-and-drop interface, what you see is what you get</li><li><strong>Sound Preview</strong>: Real-time preview of sound effects</li><li><strong>Batch Processing</strong>: Support for batch import and editing of sound effects</li><li><strong>Version Compatibility</strong>: Supports the latest version of Minecraft while being compatible with older versions</li><li><strong>Project Management</strong>: Easily manage multiple music pack projects</li></ul><h3 id="open-source-and-free" tabindex="-1">Open Source and Free <a class="header-anchor" href="#open-source-and-free" aria-label="Permalink to &quot;Open Source and Free&quot;">​</a></h3><p>MinecraftSounds is an open-source project, completely free to use. We believe that through community power, this tool can become even more powerful and user-friendly.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>Ready to start creating your first music pack? Check out our <a href="/en/guide/getting-started.html">Getting Started</a> guide to learn how to install and use the MinecraftSounds Music Pack Generator.</p><p>If you already have some experience, you can go directly to the <a href="/en/tutorials/">Tutorials</a> section to learn how to use more advanced features.</p>',17)]))}const f=t(r,[["render",i]]);export{p as __pageData,f as default};
